package com.example.urlshortener.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="idempotency_records") public class IdempotencyRecord { @Id private String keyValue; @Column(nullable=false) private UUID shortUrlId; @Column(nullable=false) private String requestFingerprint; @Column(nullable=false) private Instant createdAt; protected IdempotencyRecord(){} public IdempotencyRecord(String keyValue,UUID shortUrlId,String requestFingerprint){this.keyValue=keyValue;this.shortUrlId=shortUrlId;this.requestFingerprint=requestFingerprint;this.createdAt=Instant.now();} public String getKeyValue(){return keyValue;} public UUID getShortUrlId(){return shortUrlId;} public String getRequestFingerprint(){return requestFingerprint;} }
